async function loadMotion(file){let candidate;try{if(file.size>48*1024*1024)throw new Error('모션 파일은 48MB 이내로 선택해 주세요.');const ext=file.name.split('.').pop().toLowerCase(),buf=await file.arrayBuffer();if(ext==='vmd'){const parsed=parseVMD(buf),mapped=vmdMapping(parsed);if(!mapped.length)throw new Error('연결할 수 있는 MMD 표준 본이 없습니다.');candidate={type:'vmd',name:file.name,duration:parsed.duration,mapped};}else if(ext==='fbx'){const source=new FBXLoader().parse(buf,'');if(!source.animations.length)throw new Error('FBX 파일에 애니메이션이 없습니다.');source.updateMatrixWorld(true);const sourceBones=[];source.traverse(o=>{if(o.isBone)sourceBones.push(o);});const clean=n=>n.replace(/^mixamorig:?/i,'').replace(/[^a-z]/gi,'').toLowerCase();const targetNames={hips:2,spine:3,spine1:3,spine2:3,neck:4,head:5,leftshoulder:6,leftarm:7,leftforearm:8,lefthand:9,rightshoulder:10,rightarm:11,rightforearm:12,righthand:13,leftupleg:14,leftleg:15,leftfoot:16,rightupleg:17,rightleg:18,rightfoot:19};const seen=new Set(),mapped=[];for(const b of sourceBones){const i=targetNames[clean(b.name)];if(i!==undefined&&!seen.has(i)){seen.add(i);mapped.push({i,source:b,restWorld:b.getWorldQuaternion(new T.Quaternion()),restPosition:b.getWorldPosition(new T.Vector3())});}}if(!mapped.length)throw new Error('Mixamo 또는 표준 휴머노이드 본을 찾을 수 없습니다.');mapped.sort((a,b)=>a.i-b.i);const box=new T.Box3().setFromObject(source);const height=box.getSize(new T.Vector3()).y;const mixer=new T.AnimationMixer(source);mixer.clipAction(source.animations[0]).play();candidate={type:'fbx',name:file.name,source,mixer,mapped,duration:source.animations[0].duration,scale:3/Math.max(height,1)};}else throw new Error('VMD 또는 FBX 모션 파일을 선택해 주세요.');if(!Number.isFinite(candidate.duration)||candidate.duration<=0)throw new Error('재생 가능한 모션 길이가 없습니다.');clearMotion(false);externalMotion=candidate;duration=candidate.duration;$('#timeline').max=duration;time=0;running=true;syncUI();$('#motion-status').textContent=`${file.name} · ${duration.toFixed(1)}초 · ${candidate.mapped.length}개 본 연결. 본 비율에 따라 동작이 달라질 수 있어요.`;toast('모션을 불러왔어요.');}catch(e){if(candidate?.source){candidate.mixer.uncacheRoot(candidate.source);}toast(e.message||'모션 파일을 불러올 수 없습니다.');}}
function applyFBX(t,target=avatar){const ext=externalMotion;resetPose(target);target.root.updateMatrixWorld(true);const rest=target.bones.map(b=>b.getWorldQuaternion(new T.Quaternion()));ext.mixer.setTime(t);ext.source.updateMatrixWorld(true);for(const m of ext.mapped){const delta=m.source.getWorldQuaternion(new T.Quaternion()).multiply(m.restWorld.clone().invert());const desired=delta.multiply(rest[m.i]);const parent=target.bones[m.i].parent.getWorldQuaternion(new T.Quaternion()).invert();target.bones[m.i].quaternion.copy(parent.multiply(desired));if(m.i===2){const pos=m.source.getWorldPosition(new T.Vector3()).sub(m.restPosition).multiplyScalar(ext.scale);target.bones[1].position.add(pos);}target.root.updateMatrixWorld(true);}}
for(const zone of[stage,$('#import-motion')]){zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');const file=e.dataTransfer.files[0];if(!file)return;if(/\.(vmd|fbx)$/i.test(file.name))loadMotion(file);else loadProject(file);});}
const dialog=$('#export-dialog');$('#export-open').addEventListener('click',()=>dialog.showModal());$('#export-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function compositeFrame(width=canvas.width,height=canvas.height,transparent=state.background==='transparent',forceOpaque=false){renderFrame();const out=document.createElement('canvas');out.width=width;out.height=height;const c=out.getContext('2d');const clear=transparent&&!forceOpaque;if(!clear){if(state.background==='image'){drawBackgroundPhoto(c,width,height,state);}else if(state.background==='solid'||(forceOpaque&&state.background==='transparent')){c.fillStyle=state.backgroundColor;c.fillRect(0,0,width,height);}else{const g=c.createRadialGradient(width*.46,height*.36,0,width*.5,height*.5,width*.72);const colors={soft:['#faf8f4','#e7e2da'],retro:['#eceee5','#dbe0d4'],lowpoly:['#f5f3ef','#e3e0da'],sunset:['#fff1de','#eccdbe']}[state.filter];g.addColorStop(0,colors[0]);g.addColorStop(1,colors[1]);c.fillStyle=g;c.fillRect(0,0,width,height);}if(state.background==='mood'||state.background==='grid'){c.strokeStyle='#ffffff45';c.lineWidth=.7;const top=state.background==='grid'?0:height*.56;for(let x=0;x<width;x+=38*width/stage.clientWidth){c.beginPath();c.moveTo(x,top);c.lineTo(x,height);c.stroke();}for(let y=top;y<height;y+=38*height/stage.clientHeight){c.beginPath();c.moveTo(0,y);c.lineTo(width,y);c.stroke();}}}c.imageSmoothingEnabled=state.filter!=='retro';c.drawImage(canvas,0,0,width,height);return out;}
async function capture(includeBackground=false){if(!renderer){toast('3D 화면이 아직 준비되지 않았어요.');return;}flushRebuild();samplePose(time);const backdrop=includeBackground===true;try{if(backdrop)await ensureBackgroundImage(state);const old=pedestal.visible,oldGround=ground.visible;let frame;try{if(!backdrop){pedestal.visible=false;ground.visible=false;}frame=compositeFrame(Math.round(stage.clientWidth*2),Math.round(stage.clientHeight*2),!backdrop||state.background==='transparent',false);}finally{pedestal.visible=old;ground.visible=oldGround;renderFrame();}frame.toBlob(blob=>{download(blob,`${fileName()}${backdrop?'-배경포함':''}.png`,'image/png');toast(backdrop?'캐릭터와 배경을 PNG로 저장했어요.':'지금 보이는 캐릭터만 투명 PNG로 저장했어요.');});dialog.close();}catch(e){toast(e.message||'PNG를 저장할 수 없습니다.');}}$('#capture').addEventListener('click',()=>capture());$('#export-png').addEventListener('click',()=>capture());$('#export-png-background').addEventListener('click',()=>capture(true));
async function exportMMD(){flushRebuild();if(!getEditingAvatar())return;const state=structuredClone(getEditingState()),avatar=buildAvatar(state);try{const{bytes,textures}=exportPMX(avatar,state);const images={};for(const {texture,name}of textures){const png=texture.image.toDataURL('image/png').split(',')[1];images[name]=Uint8Array.from(atob(png),c=>c.charCodeAt(0));}const zip=zipSync({'character.pmx':bytes,...images,'project.json':strToU8(JSON.stringify({...project(),state},null,2)),'읽어주세요.txt':strToU8('Pixel Pals · 직접 제작한 캐릭터\ncharacter.pmx와 포함된 모든 PNG를 같은 폴더에 두고 MMD에 불러오세요.\n본과 다리 IK를 포함합니다. 표정 모프와 물리는 포함하지 않습니다.\nproject.json 또는 이 ZIP으로 이 공방에서 다시 편집할 수 있습니다.\nMMD 데스크톱 프로그램에서의 최종 재생 호환성은 별도 확인이 필요합니다.\n')});download(zip,`${fileName()}-MMD.zip`,'application/zip');dialog.close();toast('PMX 모델과 텍스처를 함께 저장했어요.');}catch(e){console.error(e);toast('MMD 모델 저장 중 문제가 발생했습니다.');}finally{disposeAvatar(avatar);}}$('#export-pmx').addEventListener('click',exportMMD);
async function exportGLB(){flushRebuild();if(!getEditingAvatar())return;const state=structuredClone(getEditingState()),avatar=buildAvatar(state);let skin;try{skin=skinnedAvatar(avatar,state);const model=await new GLTFExporter().parseAsync(skin.root,{binary:true,onlyVisible:true});download(model,`${fileName()}.glb`,'model/gltf-binary');dialog.close();toast('관절이 포함된 GLB 모델을 저장했어요.');}catch(e){console.error(e);toast('GLB 모델 저장 중 문제가 발생했습니다.');}finally{skin?.geometry.dispose();skin?.root.traverse(o=>{if(o.skeleton)o.skeleton.dispose();});disposeAvatar(avatar);}}$('#export-glb').addEventListener('click',exportGLB);
function syncRecordSize(){const options=$('#gif-size-options');options.hidden=$('#record-format').value!=='gif';const width=Number($('#gif-width').value);$('#gif-dimensions').textContent=width+' × '+Math.round(width*stage.clientHeight/stage.clientWidth)+'px';}
$('#record-format').addEventListener('change',syncRecordSize);$('#gif-width').addEventListener('change',syncRecordSize);syncRecordSize();
async function recordGif(seconds,oldTime){
 const[{GIFEncoder},{createGifColorMap}]=await Promise.all([import('./vendor/gifenc.js'),import('./gif-colors.js')]);
 const gif=GIFEncoder(),selected=Number($('#gif-width').value),w=[360,540,720,960].includes(selected)?selected:720,h=Math.round(w*stage.clientHeight/stage.clientWidth),fps=12,frames=Math.ceil(seconds*fps),transparent=state.background==='transparent';
 renderer.setPixelRatio(1);renderer.setSize(w,h,false);
 function framePixels(i){
  time=oldTime+i/fps*(externalMotion?state.speed:1);if(externalMotion)time%=duration;samplePose(time);
  return compositeFrame(w,h).getContext('2d',{willReadFrequently:true}).getImageData(0,0,w,h).data;
 }
 const collector=createGifColorMap({transparent}),samples=Math.min(8,frames);
 for(let i=0;i<samples;i++){
  collector.sample(framePixels(Math.round(i*(frames-1)/(samples-1))));
  $('#record').textContent='GIF 색상 준비 중…';await new Promise(resolve=>setTimeout(resolve,0));
 }
 const colors=collector.finish();
 for(let i=0;i<frames;i++){
  const index=colors.mapFrame(framePixels(i));
  gif.writeFrame(index,w,h,{palette:i===0?colors.palette:undefined,delay:1000/fps,repeat:0,transparent,transparentIndex:Math.max(0,colors.transparentIndex),dispose:2});
  if(i%3===0){$('#record').textContent=`GIF 촬영 중 ${Math.round(i/frames*100)}%`;await new Promise(resolve=>setTimeout(resolve,0));}
 }
 gif.finish();download(gif.bytes(),`${fileName()}.gif`,'image/gif');
}
async function record(){if(recording||!renderer)return;flushRebuild();const seconds=Number($('#record-duration').value);if(!Number.isFinite(seconds)||seconds<1||seconds>20){toast('촬영 시간은 1–20초로 입력해 주세요.');return;}const format=$('#record-format').value;recording=true;const oldRunning=running,oldTime=time;running=true;$('#record').disabled=true;$('#record').innerHTML=icon('record')+' 촬영 중…';try{await ensureBackgroundImage(state);if(format==='gif'){await recordGif(seconds,oldTime);}else{if(!window.MediaRecorder)throw new Error('이 브라우저에서는 영상 녹화를 사용할 수 없습니다.');const types=format==='mp4'?['video/mp4;codecs=avc1.420028','video/mp4']:['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'];const type=types.find(x=>MediaRecorder.isTypeSupported(x));if(!type)throw new Error('이 브라우저에서는 '+(format==='mp4'?'MP4':'WebM')+' 녹화를 지원하지 않습니다. 다른 형식을 선택해 주세요.');const output=compositeFrame(960,Math.max(2,Math.round(480*stage.clientHeight/stage.clientWidth)*2),false,true);const stream=output.captureStream(60),videoTrack=stream.getVideoTracks()[0];const rec=new MediaRecorder(stream,{mimeType:type,videoBitsPerSecond:3500000});const chunks=[];const finished=new Promise((resolve,reject)=>{rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};rec.onstop=resolve;rec.onerror=reject;});const ready=new Promise(resolve=>rec.addEventListener('start',resolve,{once:true}));rec.start(100);await ready;const started=performance.now();await new Promise(resolve=>{function tick(){const elapsed=(performance.now()-started)/1000;time=oldTime+elapsed*(externalMotion?state.speed:1);if(externalMotion)time%=duration;samplePose(time);const frame=compositeFrame(output.width,output.height,false,true);output.getContext('2d').drawImage(frame,0,0);videoTrack.requestFrame?.();$('#record').textContent=`촬영 중 ${Math.ceil(Math.max(0,seconds-elapsed))}초`;if(elapsed<seconds)setTimeout(tick,1000/60);else setTimeout(resolve,100);}tick();});rec.stop();await finished;stream.getTracks().forEach(t=>t.stop());if(!chunks.some(b=>b.size))throw new Error('영상 프레임을 저장하지 못했습니다. 다시 촬영해 주세요.');download(new Blob(chunks,{type}),`${fileName()}.${format}`,format==='mp4'?'video/mp4':'video/webm');}toast('작은 친구의 움직임을 저장했어요.');}catch(e){console.error(e);toast(e.message||'녹화를 완료할 수 없습니다.');}finally{recording=false;running=oldRunning;time=oldTime;resize();dirty=true;$('#record').disabled=false;$('#record').innerHTML=icon('record')+' 모션 녹화하기';syncUI();}}$('#record').addEventListener('click',record);
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifetime=new AbortController();const tools=[{name:'read_character',description:'Read the current editable Pixel Pals character settings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>project()},{name:'configure_character',description:'Update the current character using the same controls as the editor. Changes are undoable.',inputSchema:{type:'object',properties:{settings:{type:'object'}},required:['settings'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||Object.keys(input).some(k=>k!=='settings')||!input.settings)throw new Error('settings is required');const unknown=Object.keys(input.settings).filter(k=>!(k in defaults));if(unknown.length)throw new Error('Unknown character settings');setState(input.settings);await new Promise(requestAnimationFrame);return project();}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifetime.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});}
